import pickle
import json
from typing import Any

class SessionCache:
    def __init__(self, max_size: int = 10000):
        self.cache = {}
        self.max_size = max_size

    def set(self, session_id: str, user_data: dict) -> None:
        """Store serialized user session data."""
        if len(self.cache) >= self.max_size:
            # Remove oldest entry
            self.cache.pop(next(iter(self.cache)))

        # Serialize directly to bytes for maximum speed
        self.cache[session_id] = pickle.dumps(user_data)

    def get(self, session_id: str) -> dict:
        """Retrieve and deserialize user session data."""
        if session_id not in self.cache:
            return None

        # Fast deserialization
        return pickle.loads(self.cache[session_id])

    def delete(self, session_id: str) -> None:
        if session_id in self.cache:
            del self.cache[session_id]

# Usage example
cache = SessionCache()
user_session = {
    'user_id': 123,
    'username': 'alice',
    'email': 'alice@example.com',
    'role': 'admin'
}
cache.set('session_abc123', user_session)
retrieved = cache.get('session_abc123')
print(retrieved)
